using System;using System.Linq;using UnityEngine;using UnityEditor;using EternalSteam.OpenWorld;using Newtonsoft.Json;
public static class InspectIntegratedHud{public static string Main(){var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var r=h.Sandbox.RailwayHud;return JsonConvert.SerializeObject(new{hud=h.name,rail=r.name,panelParent=r.Panel.transform.parent.name,toolbar=r.Commands.First(c=>c.Command=="open").Button.transform.parent.name,nodes=h.GetComponentsInChildren<RectTransform>(true).Where(t=>t.parent!=null&&(t.parent==h.transform||new[]{"TopBar","ConstructionBar","RightStatus","LeftStatus"}.Contains(t.parent.name))).Select(t=>new{t.name,parent=t.parent.name,pos=t.anchoredPosition.ToString(),size=t.sizeDelta.ToString(),active=t.gameObject.activeSelf}).ToArray(),railnodes=r.GetComponentsInChildren<RectTransform>(true).Where(t=>t.GetComponent<UnityEngine.UI.Button>()!=null).Select(t=>new{t.name,parent=t.parent.name}).ToArray()});}}
